<style>
  body {
    background-color: #f0e9d8;
    font-family: 'Georgia', 'Times New Roman', serif;
    color: #2b2b2b;
    max-width: 1400px;
    margin: 0 auto;
    padding: 30px 50px;
  }

  .page-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    border-bottom: 1px solid #2b2b2b;
    margin-bottom: 20px;
    padding-bottom: 5px;
  }

  .page-number {
    font-size: 1.1em;
  }

  .page-title {
    font-size: 1.8em;
    letter-spacing: 8px;
    text-align: center;
    flex-grow: 1;
    font-weight: normal;
  }

  .columns {
    display: flex;
    gap: 40px;
  }

  .column {
    flex: 1;
    text-align: justify;
    font-size: 1.05em;
