    margin-bottom: 15px;
  }

  p {
    margin: 0 0 12px 0;
    text-indent: 25px;
  }

  .letter-block {
    margin: 0 0 15px 0;
  }

  .letter-block p {
    text-indent: 25px;
    margin: 0 0 8px 0;
  }

  .signature {
    text-align: right;
    margin-right: 60px;
    margin-top: 10px;
  }

  .signature .closing {
    display: block;
  }

  .letter-p-noindent {
    text-indent: 0;
  }

  .bold-text {
